templates:
QWidget {{ background-color: {0}; color: {1};
           font-family: 'Segoe UI Variable Text', 'Segoe UI', sans-serif; font-size: 13px; }}
QLabel {{ background: transparent; }}
QToolTip {{ background-color: {2}; color: {3}; border: 1px solid {4}; padding: 6px; }}

/* Sidebar */
QFrame#sidebar {{ background-color: {5}; border-right: 1px solid {6}; }}
QFrame#sidebar QWidget {{ background-color: transparent; }}
QLabel#brand {{ font-size: 20px; font-weight: 800; letter-spacing: 2px; color: {7}; }}
QLabel#brandVersion {{ font-size: 11px; color: {8}; }}
QLabel#navSection {{ font-size: 10px; font-weight: 700; letter-spacing: 1px; color: {9};
                      padding: 14px 10px 4px 10px; }}
QMenu {{ background-color: {10}; color: {11}; border: 1px solid {12};
         border-radius: 8px; padding: 4px; font-size: 13px; }}
QMenu::item {{ background: transparent; padding: 5px 22px 5px 10px; border-radius: 5px; min-width: 140px; }}
QMenu::item:selected {{ background-color: {13}; color: {14}; }}
QMenu::item:disabled {{ color: {15}; }}
QMenu::separator {{ height: 1px; background: {16}; margin: 3px 6px; }}
QMenu::indicator {{ width: 14px; height: 14px; left: 8px; }}
QPushButton[role="nav"] {{ background: transparent; color: {17}; border: none;
    border-radius: 8px; padding: 7px 12px; text-align: left; font-size: 13px; }}
QPushButton[role="nav"]:hover {{ background-color: {18}; color: {19}; }}
QPushButton[role="nav"]:checked {{ background-color: {20}; color: {21}; font-weight: 600; }}
QFrame#updateBar {{ background-color: {22}; border-bottom: 1px solid {23};
    border-left: 3px solid {24}; }}
QFrame#updateBar QLabel {{ background-color: transparent; }}
QLabel#updateBarText {{ color: {25}; font-weight: 600; }}
QFrame#sidebar QFrame#navIndicator {{ background-color: {26}; border-radius: 2px; }}
QScrollArea#navScroll {{ background: transparent; border: none; }}
QLabel#sidebarFooter {{ color: {27}; font-size: 11px; }}

/* Page headers */
QLabel#pageTitle {{ font-size: 22px; font-weight: 700; }}
QLabel#pageSubtitle {{ color: {28}; font-size: 13px; }}
QLabel#sectionTitle {{ font-size: 15px; font-weight: 600; }}

/* Cards */
QFrame[role="card"] {{ background-color: {29}; border: 1px solid {30}; border-radius: 12px; }}
QFrame[role="card"] QWidget {{ background-color: transparent; }}
QFrame[role="card"] QPushButton {{ background-color: {31}; }}
QFrame[role="card"] QPushButton[role="primary"] {{ background-color: {32}; }}
QFrame[role="card"] QPushButton[role="primary"]:disabled {{ background-color: {33}; }}
QFrame[role="card"] QLineEdit, QFrame[role="card"] QComboBox {{ background-color: {34}; }}
QFrame[role="card"] QProgressBar {{ background-color: {35}; }}
QFrame[role="card"] QTableWidget {{ background-color: {36}; }}
QLabel#cardTitle {{ color: {37}; font-size: 11px; font-weight: 700; letter-spacing: 1px; }}
QLabel#bigValue {{ font-size: 28px; font-weight: 700; }}
QLabel#cardLine {{ color: {38}; font-size: 12px; }}
QLabel#muted {{ color: {39}; font-size: 12px; }}
QLabel#good {{ color: {40}; font-weight: 600; }}
QLabel#warn {{ color: {41}; font-weight: 600; }}
QLabel#bad {{ color: {42}; font-weight: 600; }}
QFrame#notice {{ background-color: {43}; border: 1px solid {44};
                 border-left: 3px solid {45}; border-radius: 8px; }}
QFrame#notice QWidget {{ background-color: transparent; }}

/* Buttons */
QPushButton {{ background-color: {46}; color: {47}; border: 1px solid {48};
               border-radius: 8px; padding: 7px 14px; }}
QPushButton:hover {{ border-color: {49}; }}
QPushButton:disabled {{ color: {50}; border-color: {51}; }}
QPushButton[role="primary"] {{ background-color: {52}; color: {53}; border: none; font-weight: 600; }}
QPushButton[role="primary"]:hover {{ background-color: {54}; border: 1px solid {55}; }}
QPushButton[role="primary"]:disabled {{ background-color: {56}; color: {57}; }}
QPushButton[role="danger"] {{ color: {58}; }}

/* Inputs */
QLineEdit, QComboBox, QSpinBox {{ background-color: {59}; border: 1px solid {60};
    border-radius: 8px; padding: 6px 8px; color: {61}; }}
QLineEdit:focus, QComboBox:focus {{ border-color: {62}; }}
QComboBox QAbstractItemView {{ background-color: {63}; border: 1px solid {64};
    selection-background-color: {65}; color: {66}; }}
QTextEdit, QPlainTextEdit {{ background-color: {67}; border: 1px solid {68};
    border-radius: 8px; color: {69}; padding: 6px; }}
QCheckBox {{ background: transparent; spacing: 8px; }}
QCheckBox::indicator {{ width: 16px; height: 16px; border: 1px solid {70}; border-radius: 4px;
                        background-color: {71}; }}
QCheckBox::indicator:hover {{ border-color: {72}; }}
QCheckBox::indicator:checked {{ background-color: {73}; border-color: {74}; }}
QCheckBox::indicator:disabled {{ border-color: {75}; }}

/* Tables */
QTableWidget {{ background-color: {76}; alternate-background-color: {77};
    border: 1px solid {78}; border-radius: 10px; gridline-color: {79};
    color: {80}; selection-background-color: {81}; selection-color: {82}; }}
QHeaderView::section {{ background-color: {83}; color: {84}; padding: 8px;
    border: none; border-bottom: 1px solid {85}; font-weight: 600; }}
QTableCornerButton::section {{ background-color: {86}; border: none; }}

/* Progress bars */
QProgressBar {{ background-color: {87}; border: none; border-radius: 4px; height: 8px;
    text-align: center; color: transparent; }}
QProgressBar::chunk {{ background-color: {88}; border-radius: 4px; }}

/* Scrollbars */
QScrollArea {{ border: none; }}
QScrollBar:vertical {{ background: transparent; width: 10px; margin: 2px; }}
QScrollBar::handle:vertical {{ background: {89}; border-radius: 4px; min-height: 30px; }}
QScrollBar::handle:vertical:hover {{ background: {90}; }}
QScrollBar:horizontal {{ background: transparent; height: 10px; margin: 2px; }}
QScrollBar::handle:horizontal {{ background: {91}; border-radius: 4px; min-width: 30px; }}
QScrollBar::add-line, QScrollBar::sub-line {{ width: 0; height: 0; }}
QScrollBar::add-page, QScrollBar::sub-page {{ background: transparent; }}

